begin;
select no_plan();
select ok(not has_table_privilege('anon','private.admin_effects','select'),'anon cannot select journal');
select ok(not has_table_privilege('authenticated','private.admin_effects','select'),'authenticated cannot select journal');
select ok(not has_table_privilege('anon','private.admin_pending_effects','select'),'anon cannot select pending');
select ok(not has_table_privilege('authenticated','private.admin_pending_effects','select'),'authenticated cannot select pending');
select ok(not has_function_privilege('anon','public.native_admin_claim_change(uuid,uuid,uuid)','execute'),'lease service only');
select ok(not has_function_privilege('authenticated','public.native_admin_reconcile_effect(uuid,uuid)','execute'),'reconcile service only');
insert into public.profiles(id) values('00000000-0000-4000-8000-000000001930'),('00000000-0000-4000-8000-000000001931');
select * from public.operational_access_set('00000000-0000-4000-8000-000000001930','owner','grant','test:r10-review','Review test','test:r10-review',null);
create temporary table review_event(event jsonb);
insert into review_event values(jsonb_build_object('request_id','00000000-0000-4000-8000-000000001932','effect_id','00000000-0000-4000-8000-000000001933','action','delete_account','effect','clerk_delete','target_hash',repeat('d',64),'outcome','started'));
select is(public.native_admin_record_effect('00000000-0000-4000-8000-000000001930',(select event from review_event)),true,'intent');
select is((select count(*) from private.admin_pending_effects where effect_id='00000000-0000-4000-8000-000000001933'),1::bigint,'intent pending');
update public.operational_access_assignments set granted_at=now()-interval '1 day',expires_at=now()-interval '1 minute' where user_id='00000000-0000-4000-8000-000000001930' and role='owner';
select is(public.native_admin_record_effect('00000000-0000-4000-8000-000000001930',(select event||'{"outcome":"succeeded","provider_status":404}' from review_event)),true,'expired owner can complete exact intent');
select is((select provider_status from private.admin_effects where effect_id='00000000-0000-4000-8000-000000001933' and outcome='succeeded'),404::smallint,'DELETE absent recorded explicitly');
select is((select count(*) from private.admin_pending_effects where effect_id='00000000-0000-4000-8000-000000001933'),0::bigint,'success closed');
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001931',(select event||'{"outcome":"succeeded","provider_status":404}' from review_event))$$,'22023','native_admin_invalid','different actor cannot close');
update public.operational_access_assignments set expires_at=null where user_id='00000000-0000-4000-8000-000000001930' and role='owner';
update review_event set event=event||'{"effect_id":"00000000-0000-4000-8000-000000001934"}';
select public.native_admin_record_effect('00000000-0000-4000-8000-000000001930',(select event from review_event));
update public.operational_access_assignments set expires_at=now()-interval '1 minute' where user_id='00000000-0000-4000-8000-000000001930' and role='owner';
select is(public.native_admin_record_effect('00000000-0000-4000-8000-000000001930',(select event||'{"outcome":"unknown","provider_status":500}' from review_event)),true,'unknown after owner expiry');
update public.operational_access_assignments set expires_at=null where user_id='00000000-0000-4000-8000-000000001930' and role='owner';
select is((select latest_outcome from private.admin_pending_effects where effect_id='00000000-0000-4000-8000-000000001934'),'unknown','uncertain remains pending');
select is(public.native_admin_reconcile_effect('00000000-0000-4000-8000-000000001930','00000000-0000-4000-8000-000000001934'),true,'manual reconciliation appended');
select is((select count(*) from private.admin_pending_effects where effect_id='00000000-0000-4000-8000-000000001934'),0::bigint,'reconciled no longer pending');
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001930',(select event||'{"outcome":"succeeded"}' from review_event))$$,'22023','native_admin_invalid','late result after reconciliation refused');
create temporary table lease_tokens(first_token uuid,second_token uuid);
insert into lease_tokens(first_token) select public.native_admin_claim_change('00000000-0000-4000-8000-000000001930','00000000-0000-4000-8000-000000001932','00000000-0000-4000-8000-000000001931');
select ok((select first_token is not null from lease_tokens),'lease acquired');
select ok((select expires_at>clock_timestamp()+interval '470 seconds' from private.admin_change_leases where account_id='00000000-0000-4000-8000-000000001931'),'lease exceeds maximum 400s worker duration');
select is(public.native_admin_claim_change('00000000-0000-4000-8000-000000001930','00000000-0000-4000-8000-000000001934','00000000-0000-4000-8000-000000001931'),null::uuid,'live concurrent claim rejected');
update private.admin_change_leases set expires_at=clock_timestamp()-interval '1 second' where account_id='00000000-0000-4000-8000-000000001931';
update lease_tokens set second_token=public.native_admin_claim_change('00000000-0000-4000-8000-000000001930','00000000-0000-4000-8000-000000001934','00000000-0000-4000-8000-000000001931');
select ok((select second_token is not null and second_token<>first_token from lease_tokens),'expired lease replaced with new fence');
select throws_ok($$select public.native_admin_finish_change('00000000-0000-4000-8000-000000001930','https://clerk.example.invalid','{"account_id":"00000000-0000-4000-8000-000000001931","blocked":false}','sandbox','00000000-0000-4000-8000-000000001932',(select first_token from lease_tokens))$$,'40001','native_admin_lease_conflict','late old token cannot write state');
select is(public.native_admin_release_change('00000000-0000-4000-8000-000000001930','00000000-0000-4000-8000-000000001932','00000000-0000-4000-8000-000000001931',(select first_token from lease_tokens)),false,'late old token cannot release new lease');
select lives_ok($$select public.native_admin_finish_change('00000000-0000-4000-8000-000000001930','https://clerk.example.invalid','{"account_id":"00000000-0000-4000-8000-000000001931","blocked":false}','sandbox','00000000-0000-4000-8000-000000001934',(select second_token from lease_tokens))$$,'current fence may write state');
select * from finish();
rollback;
